import { Request, Response, Router } from 'express';
import { CreateProjectUseCase } from '../../../application/project/CreateProjectUseCase';
import { ListProjectsUseCase } from '../../../application/project/ListProjectsUseCase';
import { asFields, requiredString } from '../requestFields';

export class ProjectController {
  readonly router = Router();

  constructor(
    private readonly createProject: CreateProjectUseCase,
    private readonly listProjects: ListProjectsUseCase,
  ) {
    this.router.post('/projects', this.create);
    this.router.get('/projects', this.list);
  }

  private readonly create = async (req: Request, res: Response): Promise<void> => {
    const body = asFields(req.body);
    const project = await this.createProject.execute({ name: requiredString(body, 'name') });
    res.status(201).json(project);
  };

  private readonly list = async (_req: Request, res: Response): Promise<void> => {
    res.json(await this.listProjects.execute());
  };
}

